inner="\nfrom pathlib import Path\nimport json,numpy as np,torch\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,boundary,feature,_,_,_=models\ncache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\ngroups=[]\nfor role,count,initial,n in (('L_s',6300,128,1024),('U_s',56700,384,3072)):\n available=np.flatnonzero(roles==role);prior=available[np.linspace(0,count-1,initial,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(3):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=128 if role=='L_s' else 384;prior=available[np.linspace(0,len(available)-1,take,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(2):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=64 if role=='L_s' else 192;groups.append(available[np.linspace(0,len(available)-1,take,dtype=int)])\nix=np.concatenate(groups);assert len(ix)==len(np.unique(ix))==256\n\nscenes=('practical_low_suburban','practical_mid_urban','practical_low_urban')\nnamespace='phase1-source-convex-oracle-2026110211';factors=(.1,1.,10.,100.);views={};traces_info={}\nwith torch.no_grad():\n for view in ('clean',)+scenes:\n  if view=='clean':\n   received=np.asarray(clean[ix],dtype=np.float32);candidates=None\n  else:\n   cfg=Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=30.,boundary='reflect')\n   received=[];candidates=[[] for _ in factors];lengths=[]\n   for j in ix:\n    pid=str(ids[j]);session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110212,session)\n    value=np.asarray(clean[j],dtype=np.float64);signal,clean_rms=normalize_input(value[0]+1j*value[1])\n    result,meta,trace=ResidualChannel(cfg,stable_seed(2026110211,namespace,view,pid),hw).process(signal,return_traces=True)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n    h=np.asarray(trace['residual_kernel'],dtype=np.complex128);lengths.append(len(h));assert len(h)<=768\n    # Privileged: undo the simulator's known AGC and residual carrier rotation,\n    # and invert its true residual FIR; IQ-image and phase noise remain.\n    t=np.arange(len(result))/cfg.fs_hz\n    y=result.astype(np.complex128)/(10**(meta['agc_gain_db']/20))*np.exp(-2j*np.pi*meta['output_frequency_hz']*t)\n    padded=np.pad(y,(len(y),len(y)),mode='reflect');H=np.fft.fft(h,n=len(padded));Y=np.fft.fft(padded)\n    noise=float(meta['added_noise_variance_reference'])\n    for k,factor in enumerate(factors):\n     z=np.fft.ifft(Y*np.conj(H)/(np.abs(H)**2+factor*noise))[len(y):2*len(y)]\n     z,_=normalize_input(z);z*=clean_rms\n     candidates[k].append(np.stack((z.real,z.imag)).astype(np.float32))\n   received=np.stack(received);candidates=[np.stack(v) for v in candidates]\n   traces_info[view]=dict(kernel_length_min=min(lengths),kernel_length_max=max(lengths))\n  probs=[]\n  for start in range(0,len(ix),32):\n   x=core.tensor(received[start:start+32],'cpu');anchor=dura(x)\n   inputs=[x,anchor]+([] if candidates is None else [core.tensor(a[start:start+32],'cpu') for a in candidates])\n   probs.append(torch.stack([F.softmax(teacher.classify_features(teacher.features(z)),1) for z in inputs],1).cpu())\n  views[view]=np.from_dlpack(torch.cat(probs).contiguous());print('KNOWN_CHANNEL_SOURCE_PREDICTIONS_FIXED',view,flush=True)\nprint('ALL_SOURCE_PREDICTIONS_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[ix]=='L_s';assert np.all(labels[ix[~labeled]]==-1)\nref=views['clean'][:,0,:];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[ix],teacher_target);results=[]\nfor view in scenes:\n pred=views[view].argmax(2);baseline=pred[:,1]==target;row=dict(view=view,valid=int(valid.sum()),labeled=int((valid&labeled).sum()),pseudo=int((valid&~labeled).sum()),raw=int((valid&(pred[:,0]==target)).sum()),dura=int((valid&baseline).sum()),oracle_fixed_filters=[])\n for j,factor in enumerate(factors):\n  right=pred[:,j+2]==target\n  row['oracle_fixed_filters'].append(dict(noise_multiplier=factor,correct=int((valid&right).sum()),L_s_correct=int((valid&labeled&right).sum()),repairs=int((valid&~baseline&right).sum()),damages=int((valid&baseline&~right).sum())))\n results.append(row);print('KNOWN_CHANNEL_SOURCE_RESULT',json.dumps(row),flush=True)\nprint('SOURCE_KNOWN_CHANNEL_ORACLE '+json.dumps(dict(status='PRIVILEGED_SOURCE_KNOWN_CHANNEL_ORACLE',source_ids=len(ix),results=results,traces_info=traces_info,\n labels='L_s actual; U_s high-confidence clean-teacher pseudo-targets',U_s_labels_read=0,V_reads=0,test_IQ_reads=0,predictions_before_source_labels=True,\n caveat='True simulated channel kernel, residual frequency, AGC and clean-source RMS are privileged and unavailable at deployment. This finite inverse is not an upper bound. Simulator is not validated real satellite data; source experts saw source records. Previously observed Phase1 test results motivated exploration.'),ensure_ascii=False),flush=True)\n"
